def _sep(title: str = "") -> None:
    width = 76
    print("\n" + "=" * width)
    if title:
        print(title.upper().center(width))
        print("=" * width)
    else:
        print("=" * width)


def _line() -> None:
    print("-" * 76)


def fmt_result(r: Dict[str, Any]) -> str:
    b = r.get("breakdown", {})
    parts = ", ".join(f"{k}={v}" for k, v in b.items())
    tail = f"  [{parts}]" if parts else ""
    return (
        f"#{r['rank']}  {r['chunk'].metadata['doc_id']}  "
        f"{r['chunk'].metadata['title'][:44]:<44} score={r['final_score']:.3f}"
        f" (dense={r['dense']:.3f}, bm25={r['sparse_norm']:.3f}){tail}"
    )


def fmt_meta(r: Dict[str, Any]) -> str:
    m = r["chunk"].metadata
    tags = ",".join(m.get("tags") or [])
    return (
        f"      category={m.get('category')}  priority={m.get('priority')}  "
        f"date={m.get('date')}  authority={m.get('authority')}  tags=[{tags}]"
    )


def show_results(
    rag: MetadataAwareRAG,
    query: str,
    query_filter: Optional[Dict[str, Any]] = None,
    k: int = 4,
    boosts: Optional[Dict[str, Any]] = None,
    label: str = "",
    mmr: bool = False,
    mmr_lambda: float = 0.6,
) -> List[Dict[str, Any]]:
    n_cand = rag.count_matching(query_filter)
    if label:
        print(f"> {label}")
    if query_filter:
        print(f"  query: {query}")
        print(f"  filter: {json.dumps(query_filter)}  (matching chunks: {n_cand}/{len(rag.chunks)})")
    else:
        print(f"  query: {query}  (no filter; candidates: {len(rag.chunks)} chunks)")
    results = rag.retrieve(
        query, query_filter=query_filter, k=k, boosts=boosts, mmr=mmr, mmr_lambda=mmr_lambda
    )
    if not results:
        print("  (no chunks matched the metadata filter)")
        return []
    for r in results:
        print("  " + fmt_result(r))
        print("  " + fmt_meta(r))
    return results


