#!/usr/bin/env python3
"""
Metadata-Aware RAG System
=========================

A Retrieval-Augmented Generation system that:
  1. Ingests documents carrying rich metadata (source, author, date, priority,
     category, tags, authority score, ...).
  2. Chunks documents while propagating document metadata to every chunk.
  3. Builds a hybrid index: BM25 (sparse lexical) + hashing embeddings (dense
     semantic), so retrieval combines keyword and semantic relevance.
  4. Filters candidate chunks with a declarative metadata query language
     (exact match, in / nin, gt / gte / lt / lte, contains, exists, regex).
  5. Ranks candidates by relevance AND metadata signals (recency, priority,
     source authority, tag overlap) with an explainable score breakdown.
  6. Optionally reranks with Maximal Marginal Relevance (MMR) for diversity.
  7. Synthesizes grounded, cited answers from the retrieved passages.

The dense embedder is a pluggable, dependency-free feature-hashing n-gram
embedder so this runs offline. Swap HashingEmbedder for a production model
(e.g. sentence-transformers or an API embedder) by implementing the same
`embed(text) -> List[float]` interface; nothing else changes.

Run:  python3 rag_metadata_system.py
"""

from __future__ import annotations

import hashlib
import json
import math
import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

# ---------------------------------------------------------------------------
# Text utilities
# ---------------------------------------------------------------------------

STOPWORDS = set(
    """a an and are as at be but by for from has have he her his i in is it its
    of on or that the they this to was we what when which with you your our not
    no so such than too very can will just should would could do does did been
    being all any each more most other some""".split()
)


def tokenize(text: str) -> List[str]:
    text = (text or "").lower()
    tokens = re.findall(r"[a-z0-9]+(?:[-_][a-z0-9]+)*", text)
    return [t for t in tokens if t not in STOPWORDS and len(t) > 1]


def parse_date(value: Any) -> Optional[date]:
    """Parse a metadata date (datetime, date, epoch seconds, or ISO string)."""
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        return datetime.utcfromtimestamp(value).date()
    if isinstance(value, str):
        for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%Y-%m-%dT%H:%M:%S", "%d-%m-%Y"):
            try:
                return datetime.strptime(value[:19], fmt).date()
            except ValueError:
                continue
    return None


def cosine_sim(a: Sequence[float], b: Sequence[float]) -> float:
    if not a or not b:
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a)) or 1.0
    nb = math.sqrt(sum(y * y for y in b)) or 1.0
    return dot / (na * nb)


# ---------------------------------------------------------------------------
# Embeddings (pluggable dense embedder; offline hashing implementation)
# ---------------------------------------------------------------------------


class HashingEmbedder:
    """Signed feature-hashing n-gram embedder (offline, deterministic).

    Production swap-in must expose: embed(text) -> List[float].
    """

    def __init__(self, dim: int = 512, min_ngram: int = 1, max_ngram: int = 2):
        self.dim = dim
        self.min_ngram = min_ngram
        self.max_ngram = max_ngram

    def embed(self, text: str) -> List[float]:
        vec = [0.0] * self.dim
        tokens = tokenize(text)
        if not tokens:
            return vec
        for n in range(self.min_ngram, self.max_ngram + 1):
            for i in range(len(tokens) - n + 1):
                gram = " ".join(tokens[i:i + n])
                h = int(hashlib.md5(gram.encode("utf-8")).hexdigest(), 16)
                vec[h % self.dim] += 1.0 if (h >> 24) % 2 == 0 else -1.0
        norm = math.sqrt(sum(v * v for v in vec))
        return [v / norm for v in vec] if norm else vec


# ---------------------------------------------------------------------------
# Sparse lexical index (BM25)
# ---------------------------------------------------------------------------


class BM25Index:
    def __init__(
        self,
        corpus_tokens: Sequence[Sequence[str]],
        k1: float = 1.5,
        b: float = 0.75,
    ):
        self.k1 = k1
        self.b = b
        self.n_docs = len(corpus_tokens)
        self.doc_lengths = [len(d) for d in corpus_tokens]
        self.avgdl = sum(self.doc_lengths) / max(1, self.n_docs)
        self.tf = [Counter(d) for d in corpus_tokens]
        self.df: Counter = Counter()
        for c in self.tf:
            self.df.update(c.keys())
        self.idf = {
            term: math.log(1 + (self.n_docs - df + 0.5) / (df + 0.5))
            for term, df in self.df.items()
        }

    def score(self, query_terms: Sequence[str], doc_idx: int) -> float:
        dl = self.doc_lengths[doc_idx]
        s = 0.0
        for q in set(query_terms):
            idf = self.idf.get(q)
            if idf is None:
                continue
            tf = self.tf[doc_idx].get(q, 0)
            s += idf * (tf * (self.k1 + 1)) / (
                tf + self.k1 * (1 - self.b + self.b * dl / max(1e-9, self.avgdl))
            )
        return s


# ---------------------------------------------------------------------------
# Chunking with metadata propagation
# ---------------------------------------------------------------------------


@dataclass
class Chunk:
    chunk_id: str
    doc_id: str
    text: str
    metadata: Dict[str, Any]
    seq: int
    embedding: List[float] = field(default_factory=list, repr=False)
    bm25_idx: int = -1


def chunk_text(
    text: str,
    doc_id: str,
    metadata: Dict[str, Any],
    chunk_size: int = 600,
    overlap: int = 100,
) -> List[Chunk]:
    paragraphs = [p.strip() for p in re.split(r"\n\s*\n", text) if p.strip()]
    merged: List[str] = []
    buf = ""
    for p in paragraphs:
        if len(buf) + len(p) + 2 <= chunk_size:
            buf = (buf + "\n\n" + p).strip()
        else:
            if buf:
                merged.append(buf)
            if len(p) > chunk_size:
                # Hard-split an over-long paragraph on sentences.
                for s in re.split(r"(?<=[.!?])\s+", p):
                    if not s:
                        continue
                    if len(buf) + len(s) + 1 <= chunk_size:
                        buf = (buf + " " + s).strip()
                    else:
                        if buf:
                            merged.append(buf)
                        buf = s
                if buf:
                    merged.append(buf)
                    buf = ""
            else:
                buf = p
    if buf:
        merged.append(buf)

    chunks: List[Chunk] = []
    for i, part in enumerate(merged):
        meta = dict(metadata)
        meta["doc_id"] = doc_id
        meta["chunk_index"] = i
        meta["n_chunks"] = len(merged)
        chunks.append(
            Chunk(
                chunk_id=f"{doc_id}::{i}",
                doc_id=doc_id,
                text=part,
                metadata=meta,
                seq=i,
            )
        )
    return chunks


# ---------------------------------------------------------------------------
# Metadata filter language
# ---------------------------------------------------------------------------

PRIORITY_LEVELS = {"critical": 4, "high": 3, "medium": 2, "low": 1}


def _comparable(v: Any) -> Any:
    if isinstance(v, str) and v.lower() in PRIORITY_LEVELS:
        return PRIORITY_LEVELS[v.lower()]
    d = parse_date(v)
    if d is not None:
        return d.toordinal()
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        return v
    return str(v)


def _compare(op: str, doc_val: Any, query_val: Any) -> bool:
    op = op.lstrip("$") or op
    if op == "eq":
        return doc_val == query_val
    if op == "ne":
        return doc_val != query_val
    if op == "in":
        if isinstance(doc_val, (list, tuple, set)):
            return any(v in query_val for v in doc_val)
        return doc_val in query_val
    if op == "nin":
        if isinstance(doc_val, (list, tuple, set)):
            return not any(v in query_val for v in doc_val)
        return doc_val not in query_val
    if op == "gt":
        return _comparable(doc_val) > _comparable(query_val)
    if op == "gte":
        return _comparable(doc_val) >= _comparable(query_val)
    if op == "lt":
        return _comparable(doc_val) < _comparable(query_val)
    if op == "lte":
        return _comparable(doc_val) <= _comparable(query_val)
    if op == "contains":
        if isinstance(doc_val, (list, tuple, set)):
            return query_val in doc_val
        return query_val in str(doc_val)
    if op == "exists":
        return (doc_val is not None) == bool(query_val)
    if op == "regex":
        try:
            return re.search(query_val, str(doc_val)) is not None
        except re.error:
            return False
    raise ValueError(f"Unknown metadata operator: {op}")


def apply_filter(metadata: Dict[str, Any], query_filter: Optional[Dict[str, Any]]) -> bool:
    """Evaluate a metadata filter, e.g.:
    {"category": "security"}
    {"priority": {"$gte": "high"}}
    {"tags": {"$in": ["encryption", "identity"]}}
    {"date": {"$gte": "2024-01-01"}, "audience": "platform-team"}
    """
    if not query_filter:
        return True
    for key, spec in query_filter.items():
        if isinstance(spec, dict) and any(str(k).startswith("$") for k in spec):
            for op, val in spec.items():
                if not _compare(op, metadata.get(key), val):
                    return False
        else:
            if not _compare("eq", metadata.get(key), spec):
                return False
    return True


# ---------------------------------------------------------------------------
# Metadata-aware ranking
# ---------------------------------------------------------------------------

DEFAULT_BOOSTS = {
    "recency": 0.25,             # recency of the document date
    "priority": 0.25,            # doc priority level
    "authority": 0.15,           # source authority score (0..1)
    "tags": 0.35,                # overlap of query terms with doc tags
    "recency_half_life_days": 365,
}


def apply_metadata_boosts(
    item: Dict[str, Any],
    query_terms: List[str],
    boosts: Dict[str, Any],
    today: date,
) -> Dict[str, Any]:
    """Multiply base relevance by explainable metadata factors (all ~in [0.5, 1.5])."""
    meta = item["chunk"].metadata
    breakdown: Dict[str, float] = {}
    final = item["relevance"]

    w = boosts.get("recency", 0.0)
    d = parse_date(meta.get("date"))
    if w and d:
        age_days = max(0, (today - d).days)
        half = boosts.get("recency_half_life_days", 365) or 365
        freshness = 0.5 ** (age_days / half)
        final *= 1.0 + w * (freshness - 0.5)
        breakdown["recency"] = round(freshness, 3)

    w = boosts.get("priority", 0.0)
    if w:
        p = PRIORITY_LEVELS.get(str(meta.get("priority", "")).lower(), 0.7)
        p_norm = {4: 1.0, 3: 0.85, 2: 0.7, 1: 0.5}.get(p, 0.7)
        final *= 1.0 + w * (p_norm - 0.5)
        breakdown["priority"] = p_norm

    w = boosts.get("authority", 0.0)
    if w:
        a = min(1.0, max(0.0, float(meta.get("authority", 0.7) or 0.7)))
        final *= 1.0 + w * (a - 0.5)
        breakdown["authority"] = round(a, 3)

    w = boosts.get("tags", 0.0)
    if w:
        raw_tags = meta.get("tags") or []
        if isinstance(raw_tags, str):
            raw_tags = [t.strip() for t in raw_tags.split(",")]
        tag_tokens = set()
        for t in raw_tags:
            tag_tokens.update(tokenize(str(t)))
        q_set = set(query_terms)
        overlap = len(q_set & tag_tokens) / len(q_set) if q_set else 0.0
        final *= 1.0 + w * overlap
        breakdown["tag_overlap"] = round(overlap, 3)

    item["breakdown"] = breakdown
    item["final_score"] = final
    return item


def mmr_select(ranked: List[Dict[str, Any]], k: int, lambda_mult: float) -> List[Dict[str, Any]]:
    """Maximal Marginal Relevance: balance relevance with diversity of embeddings."""
    if k >= len(ranked):
        return ranked
    scores = [r["final_score"] for r in ranked]
    lo, hi = min(scores), max(scores)
    for r, s in zip(ranked, scores):
        r["_mmr_rel"] = (s - lo) / (hi - lo) if hi > lo else 1.0

    selected: List[Dict[str, Any]] = []
    remaining = list(ranked)
    while len(selected) < k and remaining:
        best_i, best_val = -1, -math.inf
        for i, r in enumerate(remaining):
            rel = r["_mmr_rel"]
            div = 0.0
            if selected:
                div = max(
                    0.0,
                    max(
                        cosine_sim(r["chunk"].embedding, s["chunk"].embedding)
                        for s in selected
                    ),
                )
            val = lambda_mult * rel - (1.0 - lambda_mult) * div
            if val > best_val:
                best_val, best_i = val, i
        sel = remaining.pop(best_i)
        sel.pop("_mmr_rel", None)
        sel["mmr_component"] = round(best_val, 4)
        selected.append(sel)
    return selected


# ---------------------------------------------------------------------------
# Main RAG engine
# ---------------------------------------------------------------------------


class MetadataAwareRAG:
    def __init__(self, embedder: Any, chunks: List[Chunk], today: Optional[date] = None):
        self.embedder = embedder
        self.chunks = chunks
        self.today = today or date.today()
        self.bm25 = BM25Index([tokenize(c.text) for c in chunks])
        for i, c in enumerate(chunks):
            c.bm25_idx = i
            c.embedding = embedder.embed(c.text)

    # -- indexing API ------------------------------------------------------
    @classmethod
    def from_documents(
        cls,
        documents: Iterable[Dict[str, Any]],
        embedder: Any,
        chunk_size: int = 600,
        overlap: int = 100,
    ) -> "MetadataAwareRAG":
        chunks: List[Chunk] = []
        for doc in documents:
            meta = {k: v for k, v in doc.items() if k != "text"}
            chunks.extend(chunk_text(doc["text"], doc["doc_id"], meta, chunk_size, overlap))
        return cls(embedder, chunks)

    def add_document(self, doc: Dict[str, Any], chunk_size: int = 600, overlap: int = 100) -> None:
        meta = {k: v for k, v in doc.items() if k != "text"}
        new_chunks = chunk_text(doc["text"], doc["doc_id"], meta, chunk_size, overlap)
        self.chunks.extend(new_chunks)
        self.bm25 = BM25Index([tokenize(c.text) for c in self.chunks])
        for i, c in enumerate(self.chunks):
            c.bm25_idx = i
            c.embedding = self.embedder.embed(c.text)

    def count_matching(self, query_filter: Optional[Dict[str, Any]]) -> int:
        return sum(1 for c in self.chunks if apply_filter(c.metadata, query_filter))

    # -- retrieval API -----------------------------------------------------
    def retrieve(
        self,
        query: str,
        query_filter: Optional[Dict[str, Any]] = None,
        k: int = 5,
        dense_weight: float = 0.7,
        boosts: Optional[Dict[str, Any]] = None,
        mmr: bool = False,
        mmr_lambda: float = 0.6,
    ) -> List[Dict[str, Any]]:
        boosts = dict(DEFAULT_BOOSTS if boosts is None else boosts)
        q_emb = self.embedder.embed(query)
        q_tokens = tokenize(query)

        scored: List[Dict[str, Any]] = []
        for c in self.chunks:
            if not apply_filter(c.metadata, query_filter):
                continue
            dense = cosine_sim(q_emb, c.embedding)
            sparse = self.bm25.score(q_tokens, c.bm25_idx)
            scored.append({"chunk": c, "dense": dense, "sparse": sparse})

        if not scored:
            return []

        sp_max = max(s["sparse"] for s in scored)
        for s in scored:
            s["sparse_norm"] = s["sparse"] / sp_max if sp_max > 0 else 0.0
            s["relevance"] = dense_weight * s["dense"] + (1.0 - dense_weight) * s["sparse_norm"]
            apply_metadata_boosts(s, q_tokens, boosts, self.today)

        scored.sort(key=lambda s: s["final_score"], reverse=True)
        ranked = mmr_select(scored, k, mmr_lambda) if mmr else scored[:k]
        for i, r in enumerate(ranked, 1):
            r["rank"] = i
        return ranked


# ---------------------------------------------------------------------------
# Grounded answer synthesis with citations
# ---------------------------------------------------------------------------


def synthesize_answer(
    question: str,
    results: List[Dict[str, Any]],
    max_sentences_per_chunk: int = 2,
) -> Tuple[str, List[int]]:
    q_tokens = set(tokenize(question))
    cited: List[int] = []
    lines: List[str] = []
    for r in results:
        chunk = r["chunk"]
        sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+", chunk.text) if s.strip()]
        scored = []
        for s in sentences:
            toks = set(tokenize(s))
            scored.append((len(toks & q_tokens), len(toks), s))
        scored.sort(key=lambda x: (-x[0], x[1]))
        keep = [s for sc, _, s in scored if sc > 0][:max_sentences_per_chunk]
        if keep:
            src = chunk.metadata.get("source") or chunk.metadata.get("doc_id")
            title = chunk.metadata.get("title", "")
            date_s = chunk.metadata.get("date", "")
            seg = " ".join(keep)
            if seg and seg[-1] not in ".!?":
                seg += "."
            lines.append(f"[{r['rank']}] ({title} | {src}, {date_s}) {seg}")
            cited.append(r["rank"])

    if not lines:
        return (
            "I could not find sufficient grounded evidence in the retrieved "
            "documents to answer this question.",
            [],
        )
    lead = (
        "Based on the retrieved passages, the most relevant information is:\n"
    )
    return lead + "\n".join(lines), cited


# ---------------------------------------------------------------------------
# Evaluation harness
# ---------------------------------------------------------------------------


def dcg_at_k(rel: Sequence[int]) -> float:
    return sum((2 ** r - 1) / math.log2(i + 2) for i, r in enumerate(rel))


def evaluate(
    rag: MetadataAwareRAG,
    cases: Sequence[Dict[str, Any]],
    k: int = 3,
    query_filter: Optional[Dict[str, Any]] = None,
    boosts: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    rows = []
    for case in cases:
        res = rag.retrieve(case["query"], query_filter=query_filter, k=k, boosts=boosts)
        ids = [r["chunk"].metadata["doc_id"] for r in res]
        relevant = set(case["relevant_doc_ids"])
        hits = [1 if d in relevant else 0 for d in ids]
        recall = sum(hits) / len(relevant) if relevant else 0.0
        mrr = 0.0
        for i, h in enumerate(hits):
            if h:
                mrr = 1.0 / (i + 1)
                break
        ideal = sorted(hits, reverse=True)
        idcg = dcg_at_k(ideal)
        ndcg = dcg_at_k(hits) / idcg if idcg else 0.0
        rows.append(
            {
                "query": case["query"],
                "retrieved": ids,
                "recall@k": round(recall, 3),
                "mrr@k": round(mrr, 3),
                "ndcg@k": round(ndcg, 3),
            }
        )
    return rows


