def _sep(title: str = "") -> None:
    width = 76
    print("\n" + "=" * width)
    if title:
        print(title.upper().center(width))
        print("=" * width)
    else:
        print("=" * width)


def _line() -> None:
    print("-" * 76)


def fmt_result(r: Dict[str, Any]) -> str:
    b = r.get("breakdown", {})
    parts = ", ".join(f"{k}={v}" for k, v in b.items())
    tail = f"  [{parts}]" if parts else ""
    return (
        f"#{r['rank']}  {r['chunk'].metadata['doc_id']}  "
        f"{r['chunk'].metadata['title'][:44]:<44} score={r['final_score']:.3f}"
        f" (dense={r['dense']:.3f}, bm25={r['sparse_norm']:.3f}){tail}"
    )


def fmt_meta(r: Dict[str, Any]) -> str:
    m = r["chunk"].metadata
    tags = ",".join(m.get("tags") or [])
    return (
        f"      category={m.get('category')}  priority={m.get('priority')}  "
        f"date={m.get('date')}  authority={m.get('authority')}  tags=[{tags}]"
    )


def show_results(
    rag: MetadataAwareRAG,
    query: str,
    query_filter: Optional[Dict[str, Any]] = None,
    k: int = 4,
    boosts: Optional[Dict[str, Any]] = None,
    label: str = "",
    mmr: bool = False,
    mmr_lambda: float = 0.6,
) -> List[Dict[str, Any]]:
    n_cand = rag.count_matching(query_filter)
    if label:
        print(f"> {label}")
    if query_filter:
        print(f"  query: {query}")
        print(f"  filter: {json.dumps(query_filter)}  (matching chunks: {n_cand}/{len(rag.chunks)})")
    else:
        print(f"  query: {query}  (no filter; candidates: {len(rag.chunks)} chunks)")
    results = rag.retrieve(
        query, query_filter=query_filter, k=k, boosts=boosts, mmr=mmr, mmr_lambda=mmr_lambda
    )
    if not results:
        print("  (no chunks matched the metadata filter)")
        return []
    for r in results:
        print("  " + fmt_result(r))
        print("  " + fmt_meta(r))
    return results


def run_demo() -> None:
    _sep("Metadata-Aware RAG System - Demo")

    # --- 1. Index build ---------------------------------------------------
    _sep("1. Ingestion & index build")
    rag = MetadataAwareRAG.from_documents(SAMPLE_DOCS, HashingEmbedder(dim=512))
    n_chunks = len(rag.chunks)
    print(f"  documents indexed : {len(SAMPLE_DOCS)}")
    print(f"  chunks produced   : {n_chunks}")
    print(f"  embedding dim     : {len(rag.chunks[0].embedding)}")
    print(f"  corpus tokens     : {sum(len(tokenize(c.text)) for c in rag.chunks)}")
    per_doc = Counter(c.metadata["doc_id"] for c in rag.chunks)
    print(f"  chunks/doc        : {dict(sorted(per_doc.items()))}")

    # --- 2. Metadata filtering -------------------------------------------
    _sep("2. Metadata filtering (retrieve only from a metadata subspace)")
    q1 = "How should we encrypt sensitive customer data at rest?"
    print("  [2a] WITHOUT metadata filter")
    show_results(rag, q1, k=4)
    print()
    print("  [2b] filter category = security")
    show_results(rag, q1, query_filter={"category": "security"}, k=4)
    print()
    print("  [2c] filter priority >= high AND date >= 2024-01-01 (range + priority operators)")
    show_results(
        rag,
        q1,
        query_filter={"priority": {"$gte": "high"}, "date": {"$gte": "2024-01-01"}},
        k=4,
    )
    print()
    print("  [2d] filter tags contains 'encryption' (list membership)")
    show_results(rag, q1, query_filter={"tags": {"$contains": "encryption"}}, k=4)

    # --- 3. Metadata-aware ranking ---------------------------------------
    _sep("3. Metadata-aware ranking (explainable score breakdown)")
    q3 = "How do we pool PostgreSQL database connections efficiently?"
    print("  Doc doc-006 (relevant answer) is from 2022, priority=low, authority=0.7,")
    print("  while doc-009 (partially related) is 2024, priority=medium, authority=0.75.")
    _line()
    print("  [3a] relevance-only ranking (all metadata boosts = 0)")
    show_results(rag, q3, k=3, boosts={k: 0.0 for k in ("recency", "priority", "authority", "tags")})
    _line()
    print("  [3b] default metadata boosts (recency=0.25, priority=0.25, authority=0.15, tags=0.35)")
    show_results(rag, q3, k=3)
    _line()
    print("  [3c] recency + priority heavy (recency=0.9, priority=0.6, authority=0.0, tags=0.0)")
    show_results(
        rag,
        q3,
        k=3,
        boosts={"recency": 0.9, "priority": 0.6, "authority": 0.0, "tags": 0.0},
    )
    _line()
    print("  [3d] same query with date filter date >= 2024-01-01 (stale doc excluded)")
    show_results(rag, q3, k=3, query_filter={"date": {"$gte": "2024-01-01"}})

    # --- 4. MMR reranking ------------------------------------------------
    _sep("4. Reranking for diversity (MMR)")
    q4 = "network access, identity, and incident security"
    print("  Query: '" + q4 + "'")
    print("  [4a] top-5 by relevance")
    show_results(rag, q4, k=5)
    _line()
    print("  [4b] top-5 after MMR reranking (lambda=0.5; relevance vs. diversity)")
    show_results(rag, q4, k=5, mmr=True, mmr_lambda=0.5)

    # --- 5. Grounded answer generation -----------------------------------
    _sep("5. Grounded answer generation with citations")
    results = rag.retrieve(q1, k=4)
    answer, cited = synthesize_answer(q1, results)
    print(f"  Question: {q1}")
    print(f"  Cited chunks: {cited}")
    print("  Answer:")
    for ln in answer.split("\n"):
        print("   " + ln)

    # --- 6. Evaluation ----------------------------------------------------
    _sep("6. Evaluation (Recall@3, MRR@3, NDCG@3 on 5 ground-truth queries)")
    rows = evaluate(rag, EVAL_CASES, k=3)
    hdr = f"{'query':<58} {'R@3':>5} {'MRR':>5} {'NDCG':>5}"
    print("  " + hdr)
    print("  " + "-" * (len(hdr) - 2))
    for r in rows:
        print(f"  {r['query'][:56]:<58} {r['recall@k']:>5} {r['mrr@k']:>5} {r['ndcg@k']:>5}")
    avg = lambda key: round(sum(r[key] for r in rows) / len(rows), 3)
    print("  " + "-" * (len(hdr) - 2))
    print(f"  {'AVERAGE':<58} {avg('recall@k'):>5} {avg('mrr@k'):>5} {avg('ndcg@k'):>5}")
    _line()
    print("  Retrieval under scoped metadata filter (category=security on the encryption case):")
    for case in EVAL_CASES:
        f = {"category": "security"} if case["relevant_doc_ids"] == ["doc-002"] else None
        res = rag.retrieve(case["query"], query_filter=f, k=3)
        ids = [r["chunk"].metadata["doc_id"] for r in res]
        print(f"    {case['query'][:52]:<54} -> {ids}")

    _sep()
    print("Demo complete. All components are dependency-free Python 3 stdlib.")
    print("Production swap-in points: HashingEmbedder -> real embedder;")
    print("in-memory scan -> ANN vector index (FAISS / Qdrant / Pinecone / Chroma).")


if __name__ == "__main__":
    run_demo()
